from dataclasses import dataclass
from datetime import datetime, timedelta
import itertools


@dataclass
class Appointment:
    id: int
    patient: str
    doctor: str
    start: datetime
    end: datetime
    cancelled: bool = False
    slot_blocked: bool = True

    def overlaps(self, start: datetime, end: datetime) -> bool:
        """True if the given [start, end) interval overlaps this appointment."""
        return start < self.end and self.start < end


class Scheduler:
    def __init__(self) -> None:
        self._id_counter = itertools.count(1)
        self._appointments: dict[int, Appointment] = {}

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")

        if start >= end:
            raise ValueError("Appointment start time must be before end time.")

        has_upcoming = any(
            appt.patient == patient and not appt.cancelled and appt.start >= now
            for appt in self._appointments.values()
        )
        if has_upcoming:
            raise ValueError(
                f"Patient '{patient}' already has an upcoming appointment."
            )

        if not self.is_free(doctor, start, end):
            raise ValueError(
                f"Doctor '{doctor}' is not available between {start} and {end}."
            )

        appt_id = next(self._id_counter)
        self._appointments[appt_id] = Appointment(
            id=appt_id,
            patient=patient,
            doctor=doctor,
            start=start,
            end=end,
        )
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an existing appointment."""
        try:
            appt = self._appointments[appointment_id]
        except KeyError:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.") from None

        if appt.cancelled:
            return

        appt.cancelled = True
        # Cancelling at least 24 hours in advance unblocks the slot; otherwise retains the block
        appt.slot_blocked = appt.start - now < timedelta(hours=24)

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            return False

        return not any(
            appt.doctor == doctor and appt.slot_blocked and appt.overlaps(start, end)
            for appt in self._appointments.values()
        )
